package cn.jingyu.deepseek;
import org.json.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.*;

/** Context compaction leaves all original messages untouched and validates the covered prefix. */
public final class ContextSummary {
 public static int covered(JSONObject chat){try{JSONObject summary=chat.optJSONObject("summary");if(summary==null||summary.optString("text").trim().isEmpty())return 0;int count=summary.optInt("count");JSONArray messages=chat.optJSONArray("messages");if(messages==null||count<1||count>=messages.length()||!summary.optString("fingerprint").equals(fingerprint(messages,count)))return 0;return count;}catch(Exception e){return 0;}}
 public static String fingerprint(JSONArray messages,int count)throws Exception {MessageDigest digest=MessageDigest.getInstance("SHA-256");for(int i=0;i<count;i++){JSONObject m=messages.getJSONObject(i);digest.update((m.optString("id")+"\u0000"+m.optString("role")+"\u0000"+m.optString("text")+"\u0000"+m.optString("status")+"\u0000"+m.optString("files")+"\n").getBytes(StandardCharsets.UTF_8));}StringBuilder b=new StringBuilder();for(byte value:digest.digest())b.append(String.format(Locale.ROOT,"%02x",value&255));return b.toString();}
 public static int target(JSONObject chat,boolean force){JSONArray messages=chat.optJSONArray("messages");if(messages==null)return 0;int current=covered(chat),length=0;for(int i=current;i<messages.length();i++){JSONObject m=messages.optJSONObject(i);if(m!=null)length+=m.optString("text").length()+m.optString("protocol").length();}if(!force&&messages.length()-current<80&&length<28000)return 0;int lastAllowed=messages.length()-(force?6:14);if(lastAllowed<=current+3)return 0;for(int i=lastAllowed-1;i>current+1;i--){JSONObject m=messages.optJSONObject(i);if(m!=null&&m.optString("role").equals("assistant")&&m.optString("status").equals("complete"))return i+1;}return 0;}
 public static JSONObject request(JSONObject chat,int target)throws Exception {JSONArray messages=chat.getJSONArray("messages");int start=covered(chat);StringBuilder source=new StringBuilder();JSONObject previous=chat.optJSONObject("summary");if(start>0)source.append("旧摘要：\n").append(previous.optString("text")).append("\n\n");int used=source.length();for(int i=start;i<target;i++){JSONObject m=messages.getJSONObject(i);JSONObject record=new JSONObject().put("number",i+1).put("role",m.optString("role")).put("text",WebResearch.clip(m.optString("text"),8000));JSONArray files=m.optJSONArray("files"),names=new JSONArray();for(int j=0;files!=null&&j<files.length();j++){JSONObject f=files.optJSONObject(j);if(f!=null)names.put(new JSONObject().put("name",f.optString("name")).put("excerpt",WebResearch.clip(f.optString("text"),1200)));}record.put("attachments",names);JSONArray generated=m.optJSONArray("artifacts"),artifacts=new JSONArray();for(int j=0;generated!=null&&j<generated.length();j++){JSONObject f=generated.optJSONObject(j);if(f!=null)artifacts.put(f.optString("name"));}record.put("generated_files",artifacts);JSONArray refs=m.optJSONArray("sources"),urls=new JSONArray();for(int j=0;refs!=null&&j<refs.length();j++){JSONObject r=refs.optJSONObject(j);if(r!=null)urls.put(r.optString("url"));}record.put("source_urls",urls);String line=record.toString();if(used+line.length()>100000)throw new IllegalStateException("待整理内容较多，请分段整理");source.append(line).append('\n');used+=line.length();}return new JSONObject().put("model","deepseek-flash").put("stream",false).put("max_tokens",4096).put("thinking",new JSONObject().put("type","disabled")).put("response_format",new JSONObject().put("type","json_object")).put("messages",new JSONArray().put(new JSONObject().put("role","system").put("content",PromptPolicy.summary())).put(new JSONObject().put("role","user").put("content",source.toString())));}
 public static JSONObject make(JSONObject chat,int count,String text)throws Exception {if(text.trim().length()<10||text.length()>12000)throw new IllegalArgumentException("摘要长度无效，请重新整理");return new JSONObject().put("count",count).put("text",text.trim()).put("fingerprint",fingerprint(chat.getJSONArray("messages"),count)).put("updated",System.currentTimeMillis()).put("edited",false);}
 public static JSONArray recall(JSONObject chat,String query){JSONArray rows=new JSONArray();JSONArray messages=chat.optJSONArray("messages");String q=WebResearch.clip(query,128).toLowerCase(Locale.ROOT);List<JSONObject> candidates=new ArrayList<>();for(int i=0;messages!=null&&i<messages.length();i++){JSONObject m=messages.optJSONObject(i);if(m==null||m.optString("status").equals("streaming"))continue;String text=m.optString("text");JSONArray files=m.optJSONArray("files");for(int j=0;files!=null&&j<files.length();j++){JSONObject f=files.optJSONObject(j);if(f!=null&&!f.optString("text").isEmpty())text+="\n[附件 "+f.optString("name")+"]\n"+f.optString("text");}String hay=text.toLowerCase(Locale.ROOT);int score=q.length()==1&&hay.contains(q)?1:0;for(int j=0;j+1<q.length();j++)if(hay.contains(q.substring(j,j+2)))score++;if(q.isEmpty()||score>0){JSONObject row=new JSONObject();ChatSession.put(row,"number",i+1);ChatSession.put(row,"role",m.optString("role"));ChatSession.put(row,"text",WebResearch.clip(text,5000));ChatSession.put(row,"score",score);candidates.add(row);}}Collections.sort(candidates,(a,b)->b.optInt("score")-a.optInt("score"));for(JSONObject row:candidates){if(rows.length()>=6)break;row.remove("score");rows.put(row);}return rows;}
}
